floor_fn:
"""
    obter_pos_l: posicao -> str
    Recebe uma posicao e devolve a componente linha da posicao.
    """
def obter_pos_l(pos: Any) -> object {
    return pos['l'];
}

test_blocks:
test "t0" {
    assert (obter_pos_l({'l': 1, 'c': 0}) == 1);;
}

test "t1" {
    assert (obter_pos_l({'l': 1, 'c': 2}) == 1);;
}

test "t2" {
    assert (obter_pos_l({'l': 3, 'c': 4}) == 3);;
}

test "t3" {
    assert (obter_pos_l({'l': 0, 'c': 2}) == 0);;
}

test "t4" {
    assert (obter_pos_l({'l': 5, 'c': 6}) == 5);;
}
